import re, sys
path = "pnach-fix/cheats/SLUS-99999_1A2B3C4D.pnach"
types = {"byte": 1, "short": 2, "word": 4, "double": 8, "beshort": 2, "beword": 4,
         "bedouble": 8, "extended": 8, "bytes": 0}
keys = {"patch", "dpatch", "gsaspectratio", "gsinterlacemode", "author",
        "description", "comment", "gametitle"}
errors, patches, aspect, group = [], {}, None, None
for number, raw in enumerate(open(path, encoding="utf-8"), 1):
    line = raw.strip()
    cut = line.find("//")
    line = (line[:cut] if cut != -1 else line).strip()
    if not line:
        continue
    if line.startswith("["):
        if not line.endswith("]") or len(line) < 3:
            errors.append(f"{number}: bad group header")
        group = line[1:-1]
        continue
    key, eq, value = (part.strip() for part in line.partition("="))
    if not eq or key not in keys:
        errors.append(f"{number}: unknown or ignored line {line!r}")
        continue
    if key == "gsaspectratio":
        aspect = value
    if key != "patch":
        continue
    if group is None:
        errors.append(f"{number}: patch outside a [group] (legacy, disables patches.zip)")
    fields = [p.strip() for p in value.split(",")]
    if len(fields) != 5:
        errors.append(f"{number}: expected 5 fields")
        continue
    place, cpu, address, kind, data = fields
    if place not in {"0", "1", "2", "3"}:
        errors.append(f"{number}: bad place {place}")
    if cpu not in {"EE", "IOP"}:
        errors.append(f"{number}: CPU must be EE or IOP, got {cpu}")
    if not re.fullmatch(r"[0-9A-Fa-f]{1,8}", address):
        errors.append(f"{number}: address {address} must be bare hex")
    if kind not in types:
        errors.append(f"{number}: unknown type {kind}")
        continue
    if not re.fullmatch(r"[0-9A-Fa-f]+", data):
        errors.append(f"{number}: data {data} must be bare hex")
        continue
    if types[kind] and int(data, 16) >= 1 << (8 * types[kind]):
        errors.append(f"{number}: data {data} does not fit in {kind}")
    patches[int(address, 16)] = (place, kind, int(data, 16))
hp, ammo = patches.get(0x0015F444), patches.get(0x0015F450)
if not hp or hp[2] != 999 or hp[0] != "1":
    errors.append(f"HP patch at 0015F444 should write 999 every frame (place 1), got {hp}")
if not ammo or ammo[2] != 99999 or ammo[0] != "1":
    errors.append(f"ammo patch at 0015F450 should write 99999 every frame (place 1), got {ammo}")
if not aspect or not re.fullmatch(r"16\s*:\s*9", aspect):
    errors.append(f"gsaspectratio should be 16:9, got {aspect!r}")
print("\n".join(errors) or "OK")
sys.exit(1 if errors else 0)
